def get_dimension_content(dim_name: str, score_pct: float) -> dict:
    """Get gold-standard content for a dimension, with score-band selection."""
    dim_data = BRIDGE_DIMENSIONS.get(dim_name)
    if not dim_data:
        return None
    
    if score_pct >= 70:
        band_key = "Strong (>=70%)"
    elif score_pct >= 50:
        band_key = "Developing (50-69%)"
    else:
        band_key = "Gap (<50%)"
    
    return {
        "id": dim_data.get("id", ""),
        "construct": dim_data.get("construct", ""),
        "description_paragraphs": dim_data["description"],
        "sub_dim_interpretation": dim_data.get("sub_dim_interpretation", {}),
        "band_narrative": dim_data["band_narratives"].get(band_key, ""),
        "overuse_risks": dim_data.get("overuse_risks", ""),
        "cross_dynamics": dim_data.get("cross_dynamics", []),
        "coaching_prompts": dim_data.get("coaching_prompts", []),
        "apac_calibration": dim_data.get("apac_calibration", []),
        "score_pct": score_pct,
        "band": band_key.split(" ")[0]
    }
